entries.commands:
# ⚠ 临时生效：重启后失效，持久化见配套条目：《netplan 永久配置 IP（Ubuntu）》
ip addr show
ip addr add {{ip_addr}}/{{prefix_len}} dev {{ifname}}
ip link set {{ifname}} up
ping -c 2 {{gateway}}

nmcli con show
nmcli con mod "{{con_name}}" ipv4.method manual ipv4.addresses {{ip_addr}}/{{prefix_len}}
nmcli con mod "{{con_name}}" ipv4.gateway {{gateway}}
nmcli con mod "{{con_name}}" ipv4.dns {{dns_ip}}
nmcli con up "{{con_name}}"

systemctl status {{service_name}} --no-pager
systemctl restart {{service_name}}
systemctl enable --now {{service_name}}
systemctl is-enabled {{service_name}}
journalctl -u {{service_name}} -n 50 --no-pager

systemctl is-enabled {{service_name}}
systemctl list-unit-files --type=service --state=enabled --no-pager
systemctl list-dependencies {{service_name}}

ss -tlnp | grep :{{port}}
ss -tlnp
ss -tlnp | grep {{pid}}

# 1) 临时生效（重启失效）
ip route add {{dest_net}}/{{prefix_len}} via {{gateway}}
ip route show
# 2) 持久化：把下面这段加进 /etc/netplan/*.yaml 的 ethernets 对应网卡下，再执行
#    routes:
#      - to: {{dest_net}}/{{prefix_len}}
#        via: {{gateway}}
netplan apply
# 3) 复核
ip route show | grep {{dest_net}}

ethtool {{ifname}}
ethtool -S {{ifname}} | head -40
ip -s link show {{ifname}}

ping -c 4 {{target}}
traceroute -n {{target}}
dig +short {{domain}}
